  // [key,title,chartKind,indicator,goal,plain,workedExample,action,limitation,
  //  question,correct,wrongA,wrongB]. Source-specific settings are examples,
  // never promises or personalised position/expiration recommendations.
  const rows=[
    ['9.1','Позиция со стопом и контракт с фиксированной выплатой','plan',null,'Сначала определить тип инструмента','В линейной позиции результат зависит от расстояния между входом и выходом. В контракте с фиксированным исходом важен результат условия к сроку завершения. Эти два вида нельзя считать одной формулой.','Учебная ставка 100, чистая выплата за успех 80%. Успех даёт +80, неудача −100. Это не то же самое, что купить 100 единиц актива и закрыть их по другой цене. Правила равенства цен и возврата нужно читать отдельно.','Найди на графике вход и возможные разные цены завершения. Отдельно посчитай фиксированный результат: он задаётся условиями контракта.','Стоп и отношение ценовых расстояний не заменяют правила фиксированной выплаты. Название «опцион» не означает одинаковые условия всех продуктов.','При ставке 100 и чистой выплате 80% сколько даёт успешный исход?','Чистый результат +80 при указанных условиях.','Всегда +100.','Результат определяется только расстоянием на графике.'],
    ['9.2','Учебный терминал: что проверить до нажатия','candle',null,'Различать параметры сделки и индикаторы','Перед действием проверь актив, тип контракта, интервал свечи, срок завершения, сумму и текущую выплату. Названия и расположение кнопок могут меняться; важно понимать назначение поля.','На учебной карточке стоят свечи 1 минута и завершение через 3 минуты. Это разные настройки: одна относится к рисунку цены, другая — к договору. Переключение свечей не обязано менять срок уже открытой позиции.','Выбери свечу и прочитай её начало и конец. Затем отдельно назови параметры, которых на одной свече нет: сумма, выплата и правило завершения.','В учебных моделях нет реального брокерского счёта. Урок не требует пополнения, загрузки документов или передачи пароля.','Интервал свечи и срок контракта — одно и то же?','Нет: это два разных параметра.','Да, всегда меняются вместе.','Да, достаточно посмотреть цвет свечи.'],
    ['9.3','Как читать карточку сигнала без слепого повторения','time',null,'Проверить данные сигнала и момент его актуальности','Карточка сигнала должна позволять определить актив, направление, время с часовым поясом, срок, цену или условие входа и ограничения. Отсутствующие поля нельзя восстанавливать по желанию.','Сигнал создан в 12:00 UTC, а приложение показывает московское время. Сначала нужно согласовать часовой пояс и время сервера. Поздний вход может иметь другую цену и другое оставшееся время, чем исходная карточка.','Посмотри, как меняется закрытие при добавлении свечей. Объясни, почему одинаковое направление при разном времени входа не означает одинаковую сделку.','Сигнал — чужая гипотеза. Опоздание, иные котировки, выплата и исполнение меняют результат; совпадение направления не гарантирует совпадение исхода.','Что делать, если в сигнале нет понятного срока и часового пояса?','Уточнить условия или пропустить действие.','Угадать по последней свече.','Увеличить сумму для компенсации опоздания.'],
    ['9.4','Обычный рынок и OTC-котировки','range',null,'Понимать источник данных','OTC означает внебиржевой рынок, но под этим названием платформы могут предлагать разные продукты и способы формирования котировок. Название пары само по себе не доказывает совпадение графиков двух источников.','На двух экранах указано EUR/USD, но один инструмент имеет добавку OTC. Нельзя переносить время, уровни и результаты с первого графика на второй без проверки спецификации и данных.','Сравни два продолжения одной модели: сходное начало не делает все дальнейшие свечи одинаковыми. Назови источник и тип инструмента до сравнения результатов.','Открытие инструмента в выходной не означает работу всех обычных валютных площадок. Условия конкретной платформы надо проверять по её документации.','Можно ли переносить сигнал только по совпадению названия пары?','Нет: сначала сверяют продукт, источник и время данных.','Да, все котировки полностью одинаковы.','Да, слово OTC ничего не меняет.'],
    ['9.5','Сводки «купить/продать» и правило «два из трёх»','average',null,'Отличать агрегированную оценку от независимых подтверждений','Техническая сводка объединяет показания нескольких расчётов по прошлым ценам. Три окна с одинаковой оценкой могут использовать одни данные или пересекающиеся интервалы. Голосование не создаёт независимости.','Два из трёх интервалов показывают «покупать». Это описание правил сервиса в момент обновления, а не вероятность успеха 2/3. Важно проверить задержку, время обновления и соответствие котировок.','Сравни цену и среднюю: линия получена из тех же свечей. Объясни, почему ещё одна производная этой цены не добавляет независимый источник информации.','Сводки меняются с приходом новой цены. Правило «2 из 3» требует отдельного теста с зафиксированными моментами получения оценок.','Означает ли два голоса из трёх вероятность выигрыша 66,7%?','Нет: число согласных оценок не является такой вероятностью.','Да, это точная статистическая вероятность.','Да, проверка истории не нужна.'],
    ['10.1','Участники Forex и торговые сессии','time',null,'Связать время наблюдения с доступной ликвидностью','Валютный рынок объединяет разных участников: банки, компании, фонды и других покупателей и продавцов. Активность зависит от времени работы площадок и участников, но расписание не определяет будущий цвет свечи.','Один и тот же час UTC может соответствовать разному местному времени после сезонного перевода часов. Поэтому рабочее окно фиксируют с часовым поясом, а не запоминают навсегда одну московскую цифру.','Сравни спокойный и направленный участки графика. В реальном журнале подпиши время источника и сессию; по модели нельзя установить, какой банк совершил сделки.','Расчётные системы и часы их работы не являются прямым сигналом цены. График не раскрывает личности или намерения участников.','Что нужно записать вместе со временем сессии?','Часовой пояс и дату, учитывая изменения расписаний.','Только обещание направления.','Название одного банка как доказанную причину каждой свечи.'],
    ['10.2','Экономический календарь и Nonfarm Payrolls','volatile',null,'Прочитать факт, ожидание и прошлое значение','В календаре различают время публикации, фактическое значение, прогноз и прошлые данные, которые могут пересматриваться. Отчёт о занятости США содержит несколько показателей: одного заголовка недостаточно.','Прогноз занятости 150 тысяч, факт 180 тысяч, прошлое значение пересмотрено вниз. Новость содержит несколько изменений одновременно. Из одного сравнения 180>150 нельзя вывести обязательное направление валютной пары.','Смотри, как расширяются свечи после добавления данных. Календарь объясняет момент возможного изменения условий, а реакцию нужно наблюдать отдельно.','Дату и время публикации проверяют в актуальном официальном календаре BLS. Правило «всегда первая пятница» ненадёжно как календарная инструкция.','Где проверять время очередного отчёта о занятости США?','В актуальном календаре BLS с учётом часового пояса.','По неизменной дате из старого видео.','По цвету последней свечи.'],
    ['10.3','Новостной импульс и возврат','volatile',null,'Разделить публикацию и наблюдаемую реакцию','После новости цена может резко пройти область, остановиться и вернуться. Первое движение и устойчивое продолжение — разные события. На быстро меняющейся цене особенно важно знать, когда именно получены данные.','За один интервал цена вышла выше области, а следующий закрылся обратно внутри. Задним числом виден возврат; в начале первого импульса его ещё не было.','Раскрой основной и другой исход. Найди момент, когда истории перестают совпадать, и не используй эту свечу в более раннем решении.','На новости возможны широкие спреды и проскальзывание. Красивый результат учебной картинки не моделирует реальное исполнение.','Можно ли по первому скачку заранее знать, что возврата не будет?','Нет: продолжение ещё неизвестно.','Да, новости всегда продолжаются в первую сторону.','Да, достаточно большого тела свечи.'],
    ['10.4','Когда отсутствие сделки является решением','volatile',null,'Сформулировать наблюдаемые условия отказа','Отказ полезен, когда условия выбранного метода не выполнены: данные задерживаются, выплата не подходит расчёту, колебания резко изменились или время важной публикации слишком близко по правилам плана.','План требует закрытия свечи, но публикация происходит раньше этого закрытия. Правильный вывод — условия текущего плана ещё не готовы, а не поиск оправдания для раннего входа.','Назови одно проверяемое условие отказа до раскрытия. После добавления свечей проверь его по тем же правилам.','Нельзя оценивать отказ только по тому, что пропущенная цена позже пошла в удобную сторону. Проверяется информация на момент решения.','Цена ушла без тебя после обоснованного отказа. Это автоматически ошибка?','Нет: решение оценивают по доступным тогда условиям.','Да, любое пропущенное движение — ошибка.','Да, теперь нужно догонять увеличенной суммой.'],
    ['11.1','RSI: уровни 30/70 и периоды 5/14','average','rsi','Прочитать изменение RSI без обещания разворота','RSI сравнивает сглаженные повышения и снижения закрытий. Значения обычно лежат от 0 до 100. Высокое значение описывает преобладание недавних повышений, а не обязанность следующей свечи упасть.','RSI(5) реагирует на более короткую историю, чем RSI(14). Два RSI не являются независимыми данными. Уровни 30, 50 и 70 служат ориентирами описания, а не долями вероятности.','Посмотри на панель RSI под свечами. Сравни её с ценой и найди участок, где высокое значение сохраняется несколько свечей подряд.','RSI не измеряет объём сделок. Короткий период может давать больше изменений и ложных пересечений.','RSI равен 70. Это вероятность падения 70%?','Нет: это значение расчёта по изменениям цены.','Да, ровно 70%.','Это число сделок продавцов.'],
    ['11.2','Stochastic: положение закрытия внутри диапазона','range','stochastic','Связать осциллятор с диапазоном цен','Stochastic сравнивает закрытие с максимумом и минимумом окна. Базовая линия %K показывает, насколько закрытие близко к верхней границе; сглаживание и %D добавляют усреднение.','В окне минимум 100, максимум 110, закрытие 108. Неcглаженная %K = 100×(108−100)/(110−100)=80. Это положение в диапазоне, а не вероятность разворота.','Сравни панель и цену. Найди закрытие рядом с верхней частью окна; затем посмотри, может ли цена продолжить рост при высоком показании.','Пересечение линий внутри 20/80 нужно отличать от подтверждённого изменения структуры. При нулевом диапазоне формулу нельзя делить на ноль.','Для минимума 100, максимума 110 и закрытия 108 базовая %K равна…','80.','8.','Вероятность падения 80%.'],
    ['11.3','MACD: две средние, сигнальная и гистограмма','average','macd','Понять, что сравнивает MACD','Линия MACD — разность быстрой и медленной экспоненциальных средних. Сигнальная линия сглаживает эту разность. Гистограмма показывает разность MACD и сигнальной линии.','Если быстрая средняя 105, медленная 103, MACD равен 2. Если сигнальная 1,5, гистограмма равна 0,5. Все три числа получены из цены, а не из объёма.','Найди на панели переходы через ноль и сравни их с предшествующими свечами. Отдельно проверь, меняет ли одно пересечение структуру цены.','Цвет гистограммы не является прямым измерением покупок или продаж. Стандартные периоды — настройка, а не гарантия результата.','Что показывает гистограмма MACD?','Разность линии MACD и сигнальной линии.','Количество банковских сделок.','Гарантированный размер следующего движения.'],
    ['11.4','SMA и EMA: быстрые и медленные средние','average','ma','Различить окно и способ усреднения','SMA одинаково взвешивает закрытия внутри окна. EMA придаёт больший вес новым значениям. Быстрая линия использует меньшее окно и может чаще менять направление.','В подборке встречается пара SMA(2) и SMA(5). Пересечение означает изменение порядка двух средних последних цен. Само по себе оно не доказывает начало длинного тренда.','Сравни две линии под графиком. Найди частые пересечения в спокойном участке и более длительное расхождение в направленном.','Нельзя заменять EMA на SMA, оставив прежние результаты теста: это другое правило. Настройки 2/5 рассматриваются как вариант из материала.','Что меняется при замене SMA на EMA?','Вес старых и новых цен, значит и значения линии.','Только название без изменения расчёта.','Появляется независимый источник объёма.'],
    ['11.5','Фракталы: почему метка появляется позже','pullback','fractals','Не использовать неподтверждённую метку','Классический верхний фрактал определяется центральной свечой с более низкими максимумами по обе стороны. Чтобы проверить правую сторону, нужны будущие относительно центра свечи.','Если для определения используются две свечи справа, метку центрального максимума нельзя считать известной на закрытии самой центральной свечи. Она подтверждается позже.','На схеме найди поворот и свечи после него. Назови момент, когда правой информации стало достаточно.','Тест, который входит по фракталу раньше его подтверждения, использует недоступные тогда данные. Смысл цвета стрелки зависит от интерфейса.','Можно ли считать двухсторонний фрактал известным в его центральной свече?','Нет: ещё нужны свечи справа.','Да, стрелка уже нарисована в истории.','Да, если центральная свеча большая.'],
    ['11.6','Канал Кельтнера: средняя и диапазон','average','keltner','Разобрать центр и ширину канала','В выбранной учебной версии центр канала — EMA, а границы удалены от него на множитель ATR. Центр описывает сглаженную цену, ширина — размер колебаний.','В подборке есть EMA 19, ATR 17 и множитель 2. Если EMA=100 и ATR=3, границы равны 94 и 106. Это пример настройки, а не рекомендация для любого инструмента.','Найди центральную и крайние линии панели. Сравни расширение канала с увеличением размеров свечей.','Касание верхней полосы может сопровождать сильный рост. Оно не обязывает цену возвращаться к центру. Разные реализации канала могут отличаться.','EMA=100, ATR=3, множитель=2. Где верхняя граница?','106.','103.','Обязательно следующая цена 106.'],
    ['11.7','Полосы Боллинджера и две ширины','average','bollinger','Отличить стандартное отклонение от ATR','В учебной версии центр Bollinger — SMA закрытий, ширина — выбранное число стандартных отклонений. Это другая мера разброса, чем ATR канала Кельтнера.','В материале встречаются одинаковые периоды 25 с множителями 2,2 и 2,8. Более широкий множитель отодвигает границы от того же центра. Две полосы не дают два независимых подтверждения.','Сравни внутренние и внешние линии панели. Проверь, означает ли выход за внешнюю полосу немедленное обратное движение на каждом участке.','Выход за полосу — наблюдение об относительном положении цены. Направленный рынок может долго идти вдоль границы.','При одном центре и разбросе какой канал шире?','С множителем 2,8 по сравнению с 2,2.','Они одинаковы при любых множителях.','Тот, у которого больше вероятность выигрыша в названии.'],
    ['11.8','Awesome Oscillator: изменение средних медианной цены','average','ao','Прочитать знак осциллятора','AO сравнивает SMA медианной цены за короткое и длинное окна. Медианная цена свечи здесь равна (High+Low)/2. Знак и изменение значения — разные характеристики.','AO может оставаться положительным, но уменьшаться. Это означает, что разность средних ещё выше нуля, хотя стала меньше. Красный цвет столбца не обязательно означает отрицательное значение.','Найди на панели столбцы над и под нулём. Отдельно сравни каждый столбец с предыдущим по высоте.','AO не является фактическим потоком покупок и продаж. Цветовое оформление отличается между платформами.','Положительный AO уменьшается. Он уже ниже нуля?','Не обязательно: знак и изменение различаются.','Да, любой уменьшающийся столбец отрицателен.','Это точное число продаж.'],
    ['11.9','Momentum: разность и относительная версия','average','momentum','Уточнять формулу перед сравнением','Momentum сравнивает текущее закрытие с прошлым. Встречается разность цен и относительная версия, умноженная на 100. У этих версий разные нейтральные уровни.','Текущая цена 105, прежняя 100. Разность равна 5; относительная версия 100×105/100=105. У первой нейтральный уровень 0, у второй 100.','Сопоставь подпись панели с её нулевым или нейтральным уровнем. Сначала прочитай формулу, потом интерпретируй знак.','Нельзя сравнивать числа разных реализаций как одинаковую шкалу. Ни одна из формул не знает будущую цену.','Чем отличаются две указанные версии Momentum?','Формулой и нейтральным уровнем.','Только цветом линии.','Обе всегда равны вероятности успеха.'],
    ['11.10','Supertrend: линия на основе ATR','average','supertrend','Понять зависимость линии от диапазона','Supertrend использует ATR и коэффициент для построения переключаемой линии относительно цены. Параметры меняют чувствительность и частоту смены состояния.','При меньшем коэффициенте граница ближе к цене и переключений обычно больше. Красно-зелёная смена описывает правило индикатора, а не гарантированный разворот рынка.','Сравни линию с закрытиями. Найди, на какой свече состояние меняется и сколько колебаний было до этого.','Настройки, подобранные по одной удачной записи, могут не работать на другом участке. Проверяется конкретная реализация и момент доступности сигнала.','Смена цвета Supertrend означает…','Сработало его расчётное условие.','Будущий разворот гарантирован.','Появился факт банковского объёма.'],
    ['11.11','Vortex: две направленные величины','average','vortex','Отделить пересечение от доказательства направления','Vortex сравнивает положительные и отрицательные межсвечные движения, нормированные на суммарный True Range окна. Линии VI+ и VI− могут часто пересекаться в ненаправленном участке.','VI+ выше VI− означает только такое соотношение расчётных величин в текущем окне. Это не доля участников, покупающих актив.','На панели найди пересечение и сопоставь его со структурой цены. Проверь противоположную ветку до вывода об устойчивости.','В материале Vortex сочетается с каналом Кельтнера. Оба используют ценовые данные, поэтому не становятся независимыми от одного совместного применения.','VI+ и VI− — это процент покупателей и продавцов?','Нет: это нормированные расчётные движения цены.','Да, точная доля участников.','Да, их сумма всегда равна 100%.'],
    ['11.12','Parabolic SAR: расчётная точка и смена стороны','average','sar','Прочитать смену стороны SAR без обещания разворота','SAR строит последовательность расчётных точек по цене и времени. Следующая точка зависит от прошлой точки, крайней цены выбранного направления и коэффициента ускорения. Это не прямое измерение скорости или объёма.','Пусть предыдущий SAR=100, крайняя цена EP=110, коэффициент AF=0,02. Предварительная следующая точка равна 100+0,02×(110−100)=100,2. Затем алгоритм проверяет пересечение и ограничения по предыдущим свечам.','Сопоставь точки панели с ценой. Найди смену стороны, затем проверь: изменилась ли уже выбранная структура максимумов и минимумов? Это разные условия.','На боковом участке переключения могут повторяться. Смена стороны не доказывает новый тренд, а её отсутствие не гарантирует продолжение. В учебной версии AF начинается с 0,02, шаг 0,02, предел 0,2; первая точка отсутствует.','SAR сменил сторону. Что можно утверждать?','Выполнилось условие алгоритма; направление будущего неизвестно.','Цена обязана начать новый тренд.','Измерена точная скорость будущего движения.'],
    ['12.1','Ликвидность и предположения о заявках','range',null,'Разделить доступную цену и невидимые заявки','Ликвидность связана с возможностью совершить сделку при заданных условиях и объёме. По одному свечному графику нельзя точно узнать, сколько чужих стопов и лимитных заявок стоит за максимумом.','За заметной вершиной могут находиться разные приказы, но без соответствующих данных это гипотеза. Выход за вершину и возврат — видимые события; точный объём исполненных чужих стопов — нет.','Найди прежний максимум, затем выход и последующую реакцию. Произнеси отдельно факт и возможное объяснение.','Фраза «цена обязана идти за ликвидностью» не является проверенным законом каждого участка. Не выдавай предположение о намерениях за наблюдаемые данные.','Можно ли по свечам точно сосчитать чужие стопы за уровнем?','Нет, для этого нужны другие данные.','Да, по длине тени известно точное число.','Да, все участники ставят одинаковые приказы.'],
    ['12.2','Выход за экстремум и обратная реакция','breakout',null,'Зафиксировать последовательность без знания будущего','Сценарий «снятия» часто описывают как выход за заметный экстремум и возврат. Удобнее сначала назвать оба видимых события, а уже потом обсуждать возможные заявки.','Прежняя вершина 110, новая цена 112, позднее закрытие 108. Видим выход и возврат. На первой цене 112 второе событие ещё не было известно.','Сравни продолжения и найди свeчу возврата. Назови, как после неё изменилось описание, не подставляя её в раннее решение.','Возврат не гарантирует длительного обратного движения. Без подтверждённого потока данных точный состав исполнившихся приказов неизвестен.','Когда в этом примере виден возврат?','После появления закрытия обратно под прежней границей.','Уже до выхода за максимум.','Когда название модели удобно для входа.'],
    ['12.3','Order Block: как задать проверяемую область','pullback',null,'Определить границы модели заранее','Термин Order Block используют для области свечи или группы свечей перед определённым импульсом. В разных методиках определения отличаются. Сначала запиши, какую свечу выбираешь, по телу или теням и какое движение считаешь импульсом.','Выбранная область 104–106 зафиксирована до возврата. Когда цена возвращается, отдельно наблюдают реакцию и нарушение области. Перерисовка зоны после каждого нарушения делает проверку бессмысленной.','Отметь границы мысленно до раскрытия. После продолжения сравни цену с теми же границами; при другом исходе не подбирай новую «правильную» свечу.','По такой области нельзя доказать присутствие конкретного крупного участника. Термин не заменяет правило отбора и проверку статистики.','Что нужно задать до теста модели OB?','Правило выбора свечи, границы и условие отмены.','Только красивое название области.','Новую удобную область после каждого результата.'],
    ['12.4','FVG: трёхсвечная геометрия и возврат','breakout',null,'Увидеть разрыв диапазонов без обещания заполнения','В распространённом определении бычий FVG есть, когда максимум первой свечи ниже минимума третьей. Область между ними отмечают как трёхсвечную особенность, а не как отсутствие всех сделок внутри второй свечи.','У первой High=100, у третьей Low=103. По выбранному определению зона 100–103 появляется только после данных третьей свечи. Она может быть частично посещена, полностью пересечена или не посещена.','Сравни три соседние свечи и отметь, когда третья стала доступна. Не считай зону известной раньше завершения её определения.','Цена не обязана заполнять каждый FVG. По геометрии трёх свечей нельзя утверждать, что внутри области вообще не было сделок.','Когда определение FVG из трёх свечей можно проверить?','После появления необходимых данных третьей свечи.','Уже на первой свече.','Только если известно обязательное будущее заполнение.'],
    ['12.5','Order Flow: каких данных не хватает свечам','candle',null,'Не подменять поток сделок цветом свечи','Order Flow обычно относится к данным сделок и заявок: например, ленте и книге заявок. OHLC сжимает интервал до четырёх цен и не содержит всей этой информации.','Две истории могут иметь одинаковые открытие, максимум, минимум и закрытие, но разный порядок сделок внутри. Одинаковая зелёная свеча не доказывает одинаковый поток заявок.','Выбери свечу и перечисли её четыре числа. Затем назови недоступное: последовательность всех сделок, их размеры и состояние книги заявок.','Тиковый объём, фактический объём и цвет свечи — разные данные. У разных инструментов и источников состав доступной информации отличается.','Показывает ли цвет свечи полную книгу заявок?','Нет: это только отношение закрытия к открытию.','Да, зелёный цвет раскрывает все покупки.','Да, RSI восстанавливает книгу заявок.'],
    ['12.6','Флаг, клин и треугольник','double',null,'Сравнивать границы и подтверждение фигуры','Флаг описывает компактную паузу после движения, клин — сужающийся участок с направленными границами, треугольник — сближение границ. Определения надо задавать заранее, а похожие контуры не обещают одинаковый выход.','Если верхние повороты снижаются, а нижние повышаются, диапазон сужается. Пока выхода не было, направление следующего движения остаётся неизвестным.','Сравни верхние и нижние повороты. Не называй выход только потому, что можно провести две красивые линии.','Нельзя выбирать масштаб и границы после результата так, чтобы каждый участок становился нужной фигурой. Условия выхода и отмены важнее названия.','Сужение диапазона уже гарантирует направление выхода?','Нет: направление ещё нужно наблюдать.','Да, всегда вверх.','Да, всегда вниз.'],
    ['12.7','Дожи, тени и поглощение: отдельные признаки','candle',null,'Не смешивать тело и весь диапазон свечи','Дожи сравнивает открытие и закрытие; длинная тень — расстояние от тела до экстремума; поглощение тела сравнивает тела двух свечей. Это разные признаки, которые могут встречаться вместе или отдельно.','У первой свечи тело 100–103, у второй 99–104. Второе тело охватывает первое. Но тени первой могли выходить за 99–104, поэтому поглощение тела ещё не означает поглощение всего диапазона.','Выбери две соседние свечи. Сначала сравни только открытия и закрытия, затем отдельно максимумы и минимумы.','Одинаковое название формы при разном месте появления не даёт одинакового торгового результата. Незакрытая свеча ещё меняется.','Поглощение тела обязательно охватывает тени?','Нет: тело и полный диапазон различаются.','Да, это одно и то же.','Да, если свеча зелёная.'],
    ['13.1','SMA(2)/SMA(5) и фракталы: условия по порядку','average','ma','Превратить вариант стратегии в список событий','В материалах есть быстрые средние 2/5 и дополнительное использование фракталов. Раздели контекст, пересечение на закрытии и подтверждение поворота. Необязательные элементы должны быть явно помечены.','Пересечение средних произошло в 10:05, а фрактал подтвердился позже. Нельзя тестировать вход в 10:05 так, будто более поздняя метка была уже известна.','Сравни быстрые и медленные линии. Отдельно назови момент появления каждого подтверждения, не пользуясь будущим.','Если часть источников использует фрактал, а часть торгует без него, это разные версии правила. Их результаты не объединяют незаметно.','Можно ли использовать поздний фрактал как раннее подтверждение?','Нет: данные ещё не были доступны.','Да, в истории метка стоит на старой свече.','Да, любые версии стратегии эквивалентны.'],
    ['13.2','Кельтнер и Vortex: совместные условия','average','keltner','Развести фильтр направления и событие','Вариант из подборки соединяет канал Кельтнера с Vortex. Для проверки нужно определить, какое положение цены служит фильтром, что считается событием и когда именно оба значения доступны.','Настройка 19/17/2 описывает канал. Она сама не задаёт условие Vortex или правила выхода. Эти поля нельзя достроить из одного прибыльного скриншота.','Сначала прочитай канал, затем отдельно проверь второе условие. Если они расходятся, зафиксируй конфликт, а не выбери удобный показатель.','Совпадение двух расчётов по цене не доказывает преимущество. Все параметры и правила тестируют на данных вне подбора.','Достаточно ли одних настроек канала для полного описания стратегии?','Нет: нужны события, отмена, выход и риск.','Да, настройки определяют всё остальное.','Да, одного прибыльного примера достаточно.'],
    ['13.3','RSI у уровня и RSI по направлению','average','rsi','Не смешивать противоположные идеи','Один вариант ищет реакцию у области, другой — продолжение направления. Одинаковое высокое значение RSI не превращает эти разные идеи в один вход.','RSI выше 70 при сильном росте можно описать как высокое значение. Для идеи возврата нужен отдельный набор событий; для продолжения — другой. Одной цифры недостаточно.','Сравни RSI и структуру цены. Сформулируй заранее, проверяешь ли возврат или продолжение, и не меняй ответ после исхода.','Правило выбора короткого срока не выводится из RSI само по себе. Срок и выплата входят в отдельную проверку.','Можно ли менять идею возврата на продолжение после неудачи без нового теста?','Нет: это уже другой набор правил.','Да, если индикатор тот же.','Да, любой RSI гарантирует подходящий срок.'],
    ['13.4','Stochastic: зона, пересечение, контекст','range','stochastic','Проверить три разных условия','В учебном варианте из материала учитываются зона осциллятора, пересечение его линий и направление структуры. Выполнение одного условия не означает выполнение остальных.','Линии пересеклись вверх ниже 20, но цена обновляет понижающиеся минимумы. Есть пересечение, но согласования со структурой пока нет.','Найди пересечение на панели и отдельно опиши повороты цены. Запиши, какой пункт выполнен, какой нет.','Указанные в источнике M1/M5 и сроки — параметры конкретного варианта, а не универсальное соответствие времени и результата.','Пересечение есть, структура противоречит фильтру. Все условия выполнены?','Нет: нужно отдельно учитывать отсутствующее условие.','Да, одного пересечения достаточно.','Да, надо просто увеличить сумму.'],
    ['13.5','Supertrend и средняя: шум коротких интервалов','average','supertrend','Проверить задержки и расходы на коротком масштабе','Вариант Supertrend со средней использует два ценовых фильтра. На коротких интервалах небольшие изменения, задержка и стоимость исполнения могут занимать большую долю движения.','Красно-зелёные переключения в боковике могут возникать часто. Удаление неудобных сигналов из теста после результата создаёт ложное впечатление устойчивости.','Просмотри все переключения видимого участка, включая неудобные. Не выбирай только то, которое совпало с красивым продолжением.','Указание 15 секунд в исходнике не делает этот интервал подходящим всем. Требуется проверка данных, задержек и конкретного продукта.','Что включать в проверку частых переключений?','Все события по заранее заданному правилу, включая неудачные.','Только прибыльные картинки.','Только последнюю удачную свечу.'],
    ['13.6','Две полосы Bollinger и реакция цены','average','bollinger','Различать выход за полосу и подтверждённый возврат','Два множителя полос показывают две удалённости от общего центра. Для варианта возврата сначала должен появиться выход, затем наблюдаемое событие возврата; для продолжения определение будет другим.','Цена вышла за широкую полосу. В одном продолжении она возвращается, в другом идёт дальше. Факт выхода общий, дальнейшие события разные.','Сравни два исхода. Назови, какая дополнительная свеча потребовалась, чтобы описать возврат, и была ли она доступна в момент первого выхода.','Нельзя одновременно считать каждое касание и сигналом возврата, и сигналом продолжения, выбирая название после результата.','Выход за широкую полосу доказывает немедленный возврат?','Нет: возврат должен появиться отдельно.','Да, полоса притягивает цену обязательно.','Да, два канала дают гарантию.'],
    ['13.7','Как собрать и проверить свою версию стратегии','plan',null,'Записать правила до подбора результата','Опиши актив и источник, период данных, условия входа, отмену, завершение, расходы и риск. Затем раздели настройку и проверку на новых данных. Менять правила после каждого неудачного примера — другая процедура.','На первых 50 участках выбраны параметры. Следующие участки проверяются с теми же параметрами, без подстройки под уже увиденный исход. Размер такой выборки — пример, а не доказанный достаточный объём.','Запиши правило для видимого участка и проверь его на другой ветке. Если описание приходится менять после результата, отметь новую версию.','Результат на небольшой выборке остаётся неопределённым. Удачный подбор и настоящее преимущество — разные утверждения.','Где проверять правило после подбора параметров?','На новых данных, не использованных для настройки.','Только на тех же удачных примерах.','На одном самом красивом участке.'],
    ['14.1','Выплата и безубыточная доля успехов','risk',null,'Считать необходимую частоту успехов','При чистой выплате r на выигранную ставку и потере всей ставки при неудаче безубыточная доля успехов равна 1/(1+r), до иных расходов и возвратов. Размер ставки сам не улучшает это условие.','При r=0,8 граница равна 1/1,8≈55,56%. При r=0,4 — 1/1,4≈71,43%. Одинаковый процент удачных исходов при разной выплате даёт разный результат.','Посчитай отдельно ставку, чистую выплату и убыток. Не путай возврат тела ставки с прибылью.','Формула относится к указанной модели. Комиссии, возвраты, изменяющиеся выплаты и размеры требуют уточнения расчёта.','При выплате 80% достаточно ли 50% успехов для нуля в этой модели?','Нет: безубыточная граница около 55,56%.','Да, всегда достаточно половины.','Да, размер ставки исправляет частоту.'],
    ['14.2','Ожидание и фактическая серия','risk',null,'Отделить средний расчёт от гарантии','В простой модели на единицу ставки ожидание равно p×r−(1−p), где p — вероятность успеха, r — чистая выплата. Оценка p по истории тоже имеет неопределённость.','При p=0,6 и r=0,8 получается 0,48−0,4=0,08 на единицу до расходов. Это средний модельный расчёт, а не обещание +8% в каждую сессию.','Проверь, откуда взята частота успехов: полная ли выборка, одинаковы ли правила, не пропущены ли плохие участки.','Положительное расчётное ожидание не запрещает серии потерь. Ошибка в оценке вероятности может изменить знак результата.','Положительное ожидание гарантирует прибыль каждой следующей попытки?','Нет: отдельные исходы и серии могут быть отрицательными.','Да, иначе ожидание не положительное.','Да, если увеличить ставку.'],
    ['14.3','Противоречивые лестницы 1–2–4 и 1–2–6','risk',null,'Проверить суммы и условия компенсации','В подборке встречаются обе лестницы. Их нельзя объединить одним названием риска. Если проценты считаются от одной исходной базы, сумма 1+2+4=7%, а 1+2+6=9%.','После потерь 1 и 2 успех на ставке 6 с чистой выплатой 40% даёт 2,4. Итог 2,4−3=−0,6, а не возврат в ноль. При выплате 80% результат будет другим.','Для каждой версии выпиши исходную базу, все ставки, выплату и итог каждой ветки. Сверь арифметику до обсуждения стратегии.','Увеличение ставки после убытка повышает возможный ущерб и не исправляет вероятность исхода. Эти лестницы здесь предмет критического разбора, не рекомендуемый план.','Чему равна сумма 1%+2%+6% от одной базы?','9%.','7%.','Всегда 0 после следующего успеха.'],
    ['14.4','Просадка и восстановление','risk',null,'Считать восстановление от новой базы','Падение и восстановление считают от разных сумм. После потери доли d нужный рост для возврата равен d/(1−d). Поэтому одинаковый процент плюса не компенсирует такой же процент минуса.','Со 100 потеряно 20: осталось 80. Для возврата к 100 нужно заработать 20 на базе 80, то есть 25%. Рост 20% дал бы только 96.','Проследи изменение исходной суммы после потери. Каждый процент подпиши вместе с базой, от которой он считается.','Расчёт восстановления не говорит, каким способом или за какой срок его можно получить. Не превращай целевую сумму в повод повышать риск.','После потери 20% какой рост нужен для возврата?','25% от оставшегося капитала.','20% от оставшегося капитала.','Любой следующий успех гарантирует возврат.'],
    ['14.5','Несколько позиций и общий риск','plan',null,'Сложить возможные потери и учесть связь','Несколько отдельных небольших позиций могут составить значительный общий риск. Похожие активы или одновременные направления могут реагировать на один фактор.','Три позиции допускают по 100 потери каждая. Общий предусмотренный убыток уже 300, а не 100. Сходное поведение активов может сделать потери одновременными.','Перед новой позицией перечисли уже открытые риски и общие факторы. Не оценивай каждую карточку изолированно.','Простая сумма не моделирует все рыночные события: гэпы и исполнение могут увеличить ущерб. Связь активов также меняется.','Три одновременно принятых риска по 100 дают предусмотренную сумму…','300 до дополнительных рисков исполнения.','100, потому что каждая позиция небольшая.','0, потому что активов несколько.'],
    ['14.6','Копирование и личная ответственность за условия','time',null,'Проверять различия между исходной и скопированной сделкой','Копирование не убирает задержку, различие цены, выплаты, размера и срока. Источник может иметь другой счёт, доступ или правила исполнения. Сначала проверяют условия, а не доверяют результату чужой картинки.','Оригинал открылся на одной цене, копия позже — на другой. Даже одинаковое направление может закончиться разными результатами к одному времени.','Сравни цены до и после добавления свечей. Назови, какие поля нужно записать для честного сравнения оригинала и копии.','Скриншот дохода не заменяет полную проверяемую историю с убытками, расходами и вводами/выводами.','Почему одинаковое направление не гарантирует совпадение результата копии?','Могут отличаться время, цена и условия.','Результат обязан совпадать всегда.','Размер депозита источника отменяет задержку.'],
    ['15.1','Дневник: запись до и после решения','plan',null,'Сохранить достаточно данных для разбора','До действия записывают контекст, условия, отмену, время и риск. После — исполнение, исход и соблюдение плана. Это позволяет отличать ошибку идеи от изменения условий или нарушения.','Запись «проиграл» не говорит, что проверить. Запись с активом, временем, источником, причиной и условием отмены позволяет воспроизвести момент решения.','Составь конспект по текущему примеру до раскрытия. После добавь только новые наблюдения, сохранив исходную версию.','Журнал нужен для проверки, а не для красивого отчёта. Не удаляй неудобные попытки и не смешивай разные версии правила.','Что нельзя менять задним числом в журнале?','Исходное объяснение, выдавая новую версию за прежнюю.','Можно добавить отдельный последующий комментарий.','Можно отметить фактический результат после завершения.'],
    ['15.2','Разбор плюса и минуса по одному шаблону','pullback',null,'Проверять одинаковые вопросы при любом исходе','Для удачного и неудачного исхода используй один список: что было известно, выполнено ли событие, соблюдён ли размер, совпало ли исполнение и что стало известно позже.','Прибыль после нарушения лимита остаётся нарушением. Убыток при соблюдённых условиях не доказывает сам по себе, что план нарушен.','Открой разные продолжения и сохрани вопросы разбора неизменными. Отдельно подпиши процесс и денежный результат.','Один исход не доказывает качество стратегии. Для проверки нужны серия и описание выборки, а не только эмоциональная оценка.','Прибыль автоматически оправдывает нарушение лимита?','Нет: процесс оценивается отдельно от исхода.','Да, любой плюс доказывает правильность.','Да, после плюса запись не нужна.'],
    ['15.3','Режим, нагрузка и остановка','range',null,'Заранее определить рабочие ограничения','Сон, перерывы и нагрузка влияют на способность следовать плану. Их полезно фиксировать как условия работы, а не объяснять ими любое движение рынка.','Если из-за усталости ты не можешь последовательно проверить пункты, пауза может быть правилом процесса. Она не предсказывает, куда пойдёт график после ухода.','Перед практикой назови своё состояние и допустимую длительность работы. После оцени, удалось ли соблюдать выбранный порядок.','Рабочий режим не создаёт рыночного преимущества сам по себе. Не нужно компенсировать пропущенный день повышенной суммой.','Хороший режим сам по себе гарантирует прибыль?','Нет: он помогает исполнению, а качество метода проверяют отдельно.','Да, стратегия и расходы больше не важны.','Да, рынок обязан компенсировать дисциплину.'],
    ['15.4','Демо, учебные цели и оценка прогресса','plan',null,'Проверять навык без обещания дохода','Учебная среда позволяет освоить интерфейс и проверить последовательность решений. Она не полностью воспроизводит реальные эмоции и исполнение. Цель обучения лучше формулировать как проверяемое действие.','Вместо «за неделю удвоить счёт» выбери «записать все решения по одному шаблону и объяснить каждую отмену». Такая цель проверяется даже при разных случайных исходах.','Пройди новую практику без подсказки будущего. Запиши, какое правило удалось применить и какую ошибку нужно исправить.','Чужие обещания минимального депозита и обязательного дохода не являются критерием готовности. Урок не требует реального пополнения.','Какая цель непосредственно проверяет учебный навык?','Последовательно разметить и объяснить решения по заданному правилу.','Обязательно получить прибыль в каждой попытке.','Срочно внести деньги после просмотра урока.']
  ];
  rows.push(
    ['15.5','Убеждение и наблюдение: проверка собственной версии','range',null,'Отличить привычную мысль от наблюдаемого факта','Мысль «после такого рисунка всегда будет рост» может казаться знакомой и убедительной. Но ощущение уверенности не добавляет данных. Полезно отдельно записывать предположение и то, что действительно доступно на графике.','До раскрытия составь две колонки: «вижу» и «ожидаю». После появления новой свечи проверь, изменились ли факты и осталось ли прежнее объяснение подходящим. Несовпадение исхода с желанием не является характеристикой твоей ценности как человека.','На одной модели выпиши факт и отдельную гипотезу. Переключи продолжение и опиши, какое новое событие изменило гипотезу.','Самонаблюдение не создаёт рыночного преимущества и не заменяет расчёт риска. Здесь упражнение по записи решений, а не диагностика личности.','Сильная уверенность в направлении является дополнительной ценой на графике?','Нет: уверенность и наблюдаемые данные различаются.','Да: ощущение уверенности гарантирует направление.','Да: знакомая картинка не может дать другой исход.'],
    ['15.6','Повторяемая учебная серия и принятие неопределённости','plan',null,'Проверить одинаковое исполнение на серии моделей','Понимание правила и его последовательное применение — разные навыки. В учебной серии заранее выбирают одно правило и одинаково записывают его выполнение в разных ситуациях. Отдельный исход не должен незаметно менять критерий проверки.','Выбери несколько учебных участков. Для каждого отметь: данные доступны, условие выполнено, риск рассчитан, ответ зафиксирован до будущего. Число выполненных пунктов относится к исполнению; результат стратегии проверяется отдельно.','Повтори разбор на другой ветке и сохрани список вопросов неизменным. В конспекте отметь одно действие, которое ты действительно выполнил до раскрытия.','Серия в тренажёре не доказывает будущую доходность и не требует перехода к реальным деньгам. Менять правило можно, но это нужно обозначить новой версией.','Что сохраняют неизменным при проверке исполнения одного правила?','Заранее заданные условия и способ фиксации решения.','Обязательный прибыльный исход каждой модели.','Увеличение риска после любого неудобного результата.']
  );
  rows.push(
    ['11.13','DeMarker: новые максимумы и минимумы окна','average','demarker','Разобрать формулу до порогового правила','DeMarker сопоставляет повышения максимумов и снижения минимумов соседних свечей. В учебной панели результат приведён к шкале 0–100; в некоторых интерфейсах та же величина записана от 0 до 1.','Если среднее положительных приращений максимумов равно 3, а среднее снижений минимумов равно 1, отношение равно 3/(3+1)=0,75, или 75 на нашей шкале. Это не вероятность следующего исхода.','Сравни линию с областями 20 и 80. Отдельно опиши касание порога, пересечение порога и последующие закрытия. Не считай их одним событием.','В подборке встречается период 10, свечи 15 секунд и срок 3 минуты, но есть оговорки автора. Это параметры примера для проверки, не универсальная инструкция. При нулевом знаменателе значение не подставляется.','DeMarker равен 75 на шкале 0–100. Что это означает?','Расчётное отношение приращений; вероятность результата не установлена.','75% гарантия роста.','Точно 75% покупателей.'],
    ['11.14','Регрессионный канал: окно, линия и отклонения','average','regression','Отличить подгонку выбранного окна от нового наблюдения','Линейная регрессия приближает выбранные закрытия прямой по индексам свечей. Границы учебного канала отстоят от неё на два среднеквадратических отклонения остатков. И окно, и правило ширины задают до проверки продолжения.','Линия вида 100 + 0,5 × номер свечи описывает наклон выбранной выборки. Новая цена может выйти за границу и продолжить движение. Выход сам по себе не доказывает возврат или разворот.','Панель показывает значения на концах скользящих окон по 20 свечей. Сравни её с отдельным примером фиксированного окна: это разные способы расчёта, их результаты нельзя смешивать.','Переносить начало или конец окна после результата — значит менять модель. Учебная реализация не заявляет полного совпадения с каналом конкретной платформы. Сроки 2/5 минут из разбора проверяют отдельно.','Можно ли передвинуть конец окна после неудачи и считать, что старый канал был известен заранее?','Нет: это новая подгонка, её нужно отдельно обозначить.','Да: все варианты линии были известны раньше.','Да: любой выход гарантирует возврат.'],
    ['11.15','Heikin Ashi: вычисленные свечи и реальные цены','candle','heikin','Не подменить цену исполнения сглаженной свечой','У Heikin Ashi закрытие — среднее O,H,L,C исходной свечи. Открытие вычисляется по предыдущим вычисленным открытию и закрытию. Максимум и минимум учитывают исходные экстремумы и вычисленное тело. Это преобразование данных.','Исходная свеча O=100,H=110,L=98,C=108. Вычисленное закрытие равно 104. Это не фактическое закрытие 108. В первой учебной свече открытие берём как среднее исходных O и C; следующие используют предыдущие HA-значения.','Сравни исходные и вычисленные закрытия на панели. Объясни, почему цвет вычисленной свечи может отличаться и почему цену исполнения берут из исходного продукта.','Сглаженная серия не создаёт новые сделки по показанным синтетическим ценам. Проверка результата по HA-цене вместо доступной цены исполнения искажает расчёт.','Можно ли автоматически считать HA-закрытие фактической ценой исполнения?','Нет: это вычисленная величина.','Да: среднее обязательно торговалось как цена закрытия.','Да: сглаживание гарантирует лучший вход.'],
    ['13.8','Два Supertrend на Heikin Ashi: отдельный вариант','average','dual-supertrend','Разделить преобразование цены и два условия индикатора','В варианте подборки используются Heikin Ashi и два Supertrend: ATR(21) × 1 и ATR(14) × 2. Сначала преобразуются свечи, затем по ним рассчитываются две линии. Это отдельное правило, а не вариант Supertrend со средней.','Первая линия сменила сторону, вторая ещё нет. В описанном варианте ожидание второй линии и закрытия свечи нужного направления — разные пункты. Одно переключение не выполняет весь список.','Сопоставь линии на панели. Назови первую смену, согласование второй и момент закрытия свечи. Результат контракта сверяют с реальными ценами, не с HA-закрытием.','Указанный срок 3 минуты — параметр примера. Две линии по одним преобразованным данным не становятся независимыми подтверждениями и не гарантируют результат.','Изменилась только первая линия. Условие согласования двух линий уже выполнено?','Нет: нужно отдельно проверить вторую линию и закрытие.','Да: одной линии всегда достаточно.','Да: Heikin Ashi отменяет остальные условия.']
  );
  rows.push(['13.9','Трёхсвечные варианты и короткий срок','candle',null,'Записать отдельные условия рисунка и цену завершения','В подборке есть разные правила: зелёная–красная–зелёная с третьим закрытием выше первого; похожий вариант с третьим максимумом выше первого; и три одноцветные закрытые свечи с ожиданием противоположного движения на следующей. Это разные версии.','У третьей свечи максимум 104, закрытие 101; у первой максимум 103, закрытие 102. Версия по максимумам выполнена, по закрытиям — нет. Для трёх одноцветных сначала нужны именно три закрытые свечи, а не три текущих цвета.','Сначала выбери версию и сравни нужные величины. Потом отдельно укажи вход и срок. Для контракта на 3 секунды нужны данные в момент этих 3 секунд; одна завершённая 15-секундная свеча их не раскрывает.','Цвета свечей не устанавливают вероятность следующего исхода. Проверка трёхсекундной сделки по закрытию 15-секундной свечи подменяет момент результата. Срок 2 минуты при 30-секундных свечах также остаётся отдельным условием.','Максимум третьей выше первого, но закрытие ниже. Одинаков ли вывод двух версий?','Нет: правила сравнивают разные цены.','Да: максимум и закрытие всегда совпадают.','Да: цвет отменяет разницу величин.']);
  rows.push(
    ['11.16','Канал Donchian: максимум и минимум окна','average','donchian','Найти границы выбранного числа свечей','В учебной версии Donchian(22) верхняя граница равна наибольшему High последних22 свечей, нижняя — наименьшему Low. Середина — полусумма двух границ. Это описание выбранного окна.','Если максимум окна110, минимум98, середина104. Добавление новой свечи или выход старой из окна могут изменить границу. Середина не является обязательной целью цены.','Сравни границы панели с экстремумами. Отметь, включает ли расчёт текущую свечу: здесь включает. Сравнение цены с прошлой границей — другое правило, которое нужно явно задать.','Канал не раскрывает будущие заявки и не гарантирует возврат в середину. Нельзя подставить последующий максимум вместо известного в момент решения.','Максимум110, минимум98. Где середина?','104: (110+98)/2.','Обязательно будущая цена закрытия110.','Это невозможно вычислить без числа покупателей.'],
    ['11.17','Schaff Trend Cycle: цепочка расчётов и настройки','average','stc','Отличить устройство STC от неизвестных настроек источника','STC последовательно преобразует разность двух средних MACD через две нормировки внутри окна со сглаживанием. Результат находится на шкале0–100. Это вычисление по ценам, а не вероятность направления.','В нашей явно выбранной учебной реализации EMA23 и EMA50, два окна10, сглаживание0,5. При нулевом диапазоне нормировки сохраняется прежнее значение, в начале0. Эти настройки не восстановлены из скрытого экрана автора.','Сначала дождись достаточной истории. Затем сравни линию с ориентирами35/65 из подборки и отдельно назови изменение наклона, пересечение порога и закрытие свечи.','В тексте исходного примера часть настроек оставлена только на экране. Совпадение названия индикатора не доказывает совпадения расчётов с нашей выбранной реализацией. Прямая линия не обещает обязательного скорого поворота.','Известны только название STC и уровни35/65. Восстановлены ли все настройки?','Нет: периоды и сглаживание требуют отдельной проверки.','Да: название задаёт единственные настройки.','Да:65 означает65% успехов.'],
    ['13.10','Donchian и STC: ранний вход или наблюдаемый поворот','average','donchian','Записать согласованные условия до результата','В подборке соединены Donchian22 и STC с уровнями65/35. Часть настроек STC в тексте не названа. Раннее ожидание поворота и вход после уже наблюдаемого изменения наклона — разные версии правила.','Цена у нижней границы канала; STC остаётся плоским в нижней зоне. Событие поворота ещё не наблюдается. В другой версии автор мог бы действовать раньше, но её нельзя задним числом объявить той же подтверждённой версией.','Сначала прочитай границу канала, затем STC. Определи выбранное событие: изменение наклона на закрытии или отдельное пересечение порога. Поля, которых нет в исходнике, не заполняются догадкой.','Срок1–2 минуты и идея движения к середине — параметры исходного примера, не обещание результата. Панель STC использует объявленную учебную реализацию, а не заявляет точное воспроизведение невидимых настроек.','Версия требует наблюдаемого поворота STC, но линия пока прямая. Условие выполнено?','Нет: ожидание поворота не равно наблюдаемому событию.','Да: будущее изменение можно считать уже известным.','Да: касание канала отменяет условие STC.']
  );
  const baseByKind=new Map(course.lessons.map(l=>[l.content.interactiveLesson.kind,l.content.interactiveLesson]));
  for(const [id,title,dependsOn] of modules)course.program.push({id,title,outcome:'Понять устройство, проверить условия и выполнить самостоятельный разбор.',dependsOn,lessons:[]});
  function barsFor(kind,indicator,seed){
    if(!indicator)return structuredClone(baseByKind.get(kind)?.bars||baseByKind.get('rise').bars);
    return Array.from({length:indicator==='stc'?96:64},(_,i)=>{const previous=100+Math.sin((i-1)/4)*4+Math.sin((i-1)/11)*3+(i-1)*.07,c=100+Math.sin(i/4)*4+Math.sin(i/11)*3+i*.07,o=i?previous:99.5,w=.5+(i+seed)%4*.2;return {o,h:Math.max(o,c)+w,l:Math.min(o,c)-w,c};});
  }
